head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST20224";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst20224.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "findDigitalAllSub");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("forward", "list");
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20224.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst20224.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        await scwin.fnSearchInit(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20224.btn_fnSearchInit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/findDigitalAll.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name reflectCorpName
 * @description reflect Corp Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.reflectCorpName = function () {
    let digitalIsuNm = $c.util.getComponent('ipt_digitalIsuNm').getValue();
    digitalIsuNm = encodeURI(digitalIsuNm);
    $c.util.getComponent('ipt_digitalIsuNm').getValue();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    scwin.setCodeName();
    scwin.reflectCorpName();
    $c.util.getComponent('ipt_beginIndex').setValue("");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
};

/**
 * @method
 * @name setDigitalInfo
 * @description set Digital Info 처리
 * @param {String} isuSrtCd isuSrtCd
 * @param {*} isuKorAbbrv isuKorAbbrv
 * @param {String} isuCd isuCd
 * @returns {void}
 * @hidden N
 */
scwin.setDigitalInfo = function (isuSrtCd, isuKorAbbrv, isuCd) {
    let str = "";
    str += "isuSrtCd : " + isuSrtCd + "\n";
    str += "isuKorAbbrv : " + isuKorAbbrv + "\n";
    str += "isuCd : " + isuCd + "\n";
    (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).setDigitalInfo === 'function' ? (scwin.openerScwin()).setDigitalInfo(isuSrtCd, isuKorAbbrv, isuCd) : void 0), $c.win.closePopup([isuSrtCd, isuKorAbbrv, isuCd]));
    this.close();
};

/**
 * @method
 * @name setCodeName
 * @description set Code Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCodeName = function () {
    $c.util.getComponent('ipt_digitalIsuCd').setValue("");
    $c.util.getComponent('ipt_digitalIsuNm').setValue("");
    let digitalIsu = $c.util.getComponent('ipt_digitalIsu').getValue(); if (digitalIsu == null) { digitalIsu = ''; }
    digitalIsu = digitalIsu.toUpperCase();
    if (digitalIsu == null) {
        return;
    }
    if (digitalIsu === "") {
        return;
    }
    $c.util.getComponent('ipt_digitalIsuCd').setValue("");
    $c.util.getComponent('ipt_digitalIsuNm').setValue(digitalIsu);
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
